        AssertRefused(AtmStatus.DailyLimitExceeded, r, d, 0, 200, Notes(0, 0, 0));
    }

    // ---- Contrôle 3 : solde ----

    [Theory]
    [InlineData(100, 100)] // pas de frais
    [InlineData(10, 10)]
