input.command:
cd /travail/Atm.Tests && cat > ZzTemp.cs <<'EOF'
namespace Atm.Tests;
public class ZzTemp
{
    [Fact]
    public void Only_fee_bug()
    {
        var cases = new List<string>();
        int[] amounts = [-10, 0, 5, .. Enumerable.Range(1, 22).Select(i => i * 10)];
        Denomination?[] jams = [null, Denomination.Fifty, Denomination.Twenty, Denomination.Ten];
        int n = 0;
        for (var b = 0; b <= 250; b += 25)
        for (var w = 0; w <= 200; w += 10)
        for (var f = 0; f <= 5; f++) for (var t = 0; t <= 5; t++) for (var d = 0; d <= 5; d++)
        foreach (var j in jams) foreach (var a in amounts)
        {
            var feeBugZone = a > 100 && w + a <= 200 && w + a + 5 > 200;
            if (feeBugZone) continue;
            var disp = new MoneyDispenser(new(f, t, d), j);
            var r = new CashMachine(disp).Execute(new(b, w), new Operation.Withdraw(a));
            // re-run oracle via reflection-free copy: simple inline
            AtmStatus exp; NoteCounts notes = default; int fee = a > 100 ? 5 : 0;
            if (a <= 0 || a % 10 != 0) exp = AtmStatus.InvalidAmount;
            else if (w + a > 200) exp = AtmStatus.DailyLimitExceeded;
            else if (a + fee > b) exp = AtmStatus.InsufficientFunds;
            else {
                var av = new NoteCounts(j == Denomination.Fifty ? 0 : f, j == Denomination.Twenty ? 0 : t, j == Denomination.Ten ? 0 : d);
                NoteCounts? best = null;
                for (var x = 0; x <= av.Fifties; x++) for (var y = 0; y <= av.Twenties; y++) for (var z = 0; z <= av.Tens; z++)
                { var c = new NoteCounts(x, y, z); if (c.Value == a && (best is null || c.Total < best.Value.Total)) best = c; }
                if (best is null) exp = AtmStatus.CannotDispense; else { exp = AtmStatus.Ok; notes = best.Value; }
            }
            n++;
            if (r.Status != exp || (exp == AtmStatus.Ok && (r.Notes != notes || r.Fee != fee || disp.Stock != new NoteCounts(f,t,d) - notes)))
                cases.Add($"{b} {w} {f}{t}{d} {j} {a}: {r.Status} vs {exp}");
        }
        Assert.True(cases.Count == 0, n + " " + string.Join("\n", cases.Take(10)));
    }
}
EOF
cd /travail && dotnet test Atm.slnx --filter ZzTemp 2>&1 | grep -E "Passed!|Failed!|vs" | head; rm Atm.Tests/ZzTemp.cs

